```c
#include "serie.h"

Serie *retorna_preenchido(int *i, Serie *serie)
{
    FILE *arquivo = fopen("streaming_db.csv", "r");
    if (arquivo == NULL)
    {
        perror("\nErro ao abrir o arquivo!\n");
        exit(1);
    }

    char *pt;
    char vetor_guarda_linha[150];

    // Pula a primeira linha (cabeçalho do CSV)
    if (!fgets(vetor_guarda_linha, 150, arquivo)) {
        fclose(arquivo);
        return NULL; 
    }

    serie = (Serie *)malloc(sizeof(Serie));
    if (serie == NULL) {
        fprintf(stderr, "Falha na alocação inicial de memória.\n");
        fclose(arquivo);
        exit(1);
    }

    // Inicializa o índice atual
    (*i) = 0; 

    while (fgets(vetor_guarda_linha, 150, arquivo) != NULL)
    {
        // Aumenta a capacidade do array conforme necessário
        serie = (Serie *)realloc(serie, ((*i) + 1) * sizeof(Serie));

        if (serie == NULL) {
            fprintf(stderr, "Falha ao realocar memória para %d séries.\n", (*i) + 1);
            fclose(arquivo);
            free(serie);
            return NULL;
        }

        pt = strtok(vetor_guarda_linha, ",");
        if (!pt) break; // Evita loop infinito se a linha estiver quebrada

        serie[*i].codigo = atoi(pt);

        pt = strtok(NULL, ",");
        if (pt) strcpy(serie[*i].titulo, pt);

        pt = strtok(NULL, ",");
        if (pt) strcpy(serie[*i].genero, pt);

        pt = strtok(NULL, ",");
        serie[*i].classificacao = atoi(pt);

        pt = strtok(NULL, ",");
        if (pt) strcpy(serie[*i].plataforma, pt);

        pt = strtok(NULL, ",");
        serie[*i].duracao_media = atoi(pt);

        pt = strtok(NULL, ",");
        serie[*i].quantidade_de_temporada = atoi(pt);

        // Aloca espaço específico para episódios dessa temporada específica
        if (serie[*i].quantidade_de_temporada > 0) {
            serie[*i].quantidade_de_ep = (int *)malloc(serie[*i].quantidade_de_temporada * sizeof(int));

            for (int j = 0; j < serie[*i].quantidade_de_temporada; j++)
            {
                pt = strtok(NULL, ", ");
                if (pt)
                    serie[*i].quantidade_de_ep[j] = atoi(pt);
            }
        } else {
            serie[*i].quantidade_de_ep = NULL; // Caso não tenha temporadas
        }

        (*i)++;
    }

    fclose(arquivo);
    return serie;
}

