Para criar uma "janela" que peça a senha, precisamos separar o **Front-end** (o lado do cliente, geralmente feito com HTML/JavaScript) do **Back-end** (o seu servidor PHP).

Aqui está um exemplo completo. O usuário abrirá uma página web, verá um campo para digitar a senha e enviará isso ao seu servidor via WebSocket.

### 1. O Front-end (`index.html`)
Crie um arquivo chamado `index.html`. Ele contém o formulário de login e a lógica para conectar ao WebSocket.

```html
<!DOCTYPE html>
<html lang="pt-br">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Login Chat</title>
    <style>
        body { font-family: sans-serif; display: flex; justify-content: center; align-items: center; height: 100vh; margin: 0; background-color: #f0f2f5; }
        .login-box { background: white; padding: 30px; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); text-align: center; }
        input { padding: 10px; width: 200px; margin-bottom: 10px; border: 1px solid #ccc; border-radius: 4px; }
        button { padding: 10px 20px; background-color: #007bff; color: white; border: none; border-radius: 4px; cursor: pointer; }
        button:hover { background-color: #0056b3; }
        #status { margin-top: 15px; font-weight: bold; }
        .success { color: green; }
        .error { color: red; }
    </style>
</head>
<body>

<div class="login-box">
    <h2>Acesso ao Chat</h2>
    <p>Por favor, insira sua senha.</p>

    <input type="password" id="senhaInput" placeholder="Digite a senha">
    <br>
    <button onclick="tentarLogin()">Entrar</button>

    <div id="status"></div>
</div>

<script src="https://cdn.ratchet.io/ratchet.min.js"></script>
<script src="https://cdn.ratchet.io/websocket.min.js"></script>
<script>
    const WSS_URL = 'ws://localhost:8080'; // Ajuste se sua porta for diferente
    let socket;

    function tentarLogin() {
        const senha = document.getElementById('senhaInput').value;
        const statusDiv = document.getElementById('status');

        if (!senha) {
            statusDiv.textContent = "Erro: Senha vazia.";
            statusDiv.className = "error";
            return;
        }

        statusDiv.textContent = "Autenticando...";
        statusDiv.className = "";

        // Envia a mensagem de autenticação para o servidor
        socket.send(JSON.stringify({
            type: 'authenticate',
            password: senha
        }));
    }

    function handleSocketMessage(msg) {
        const data = JSON.parse(msg.data);
        const statusDiv = document.getElementById('status');

        switch(data.type) {
            case 'auth_request':
                statusDiv.textContent = "Esperando senha...";
                break;
            case 'auth_success':
                statusDiv.textContent = "Sucesso! Bem-vindo ao chat.";
                statusDiv.className = "success";
                statusDiv.innerHTML += "<br><small>Clique em qualquer lugar para iniciar o chat.</small>";
                document.getElementById('senhaInput').disabled = true;
                break;
            case 'auth_failed':
                statusDiv.textContent = "Senha incorreta. Tente novamente.";
                statusDiv.className = "error";
                break;
            case 'not_authenticated':
                statusDiv.textContent = "Você não tem permissão para entrar.";
                statusDiv.className = "error";
                break;
        }
    }

    function initSocket() {
        socket = new Ratchet.WebSocket(WSS_URL);

        socket.on('connect', () => {
            console.log('Conectado ao servidor');
            // Se já estiver conectado, pode precisar de um fluxo de handshake manual dependendo da implementação do Ratchet
            // Mas no nosso caso simples, o onOpen do PHP vai receber a conexão bruta
            // E nós enviamos a senha imediatamente após conectar? 
            // Para simplificar: Vamos esperar o servidor pedir ou enviarmos automaticamente.

            // Abordagem mais robusta: Enviar senha assim que conectado
            socket.send(JSON.stringify({ type: 'authenticate', password: '' })); 
        });

        socket.on('message', handleSocketMessage);

        // Tratamento de erro de conexão
        socket.onError((err) => {
            console.error("Erro na conexão:", err);
        });
    }

    // Inicializa a conexão quando a página carrega
